Path('main/gateway_device_state.h').write_text(r'''#pragma once

#include <stdbool.h>
#include <stdint.h>

#include "gateway_events.h"

#define GATEWAY_MAX_DEVICES 16U
#define GATEWAY_MAX_ENDPOINTS_PER_DEVICE 8U
#define GATEWAY_INVALID_SHORT_ADDR 0xffffU

typedef enum { SLOT_EMPTY, SLOT_ACTIVE, SLOT_REJOIN_PENDING, SLOT_LEAVING } slot_state_t;
typedef enum { BASIC_NOT_SCHEDULED, BASIC_SCHEDULED, BASIC_COMPLETE } basic_state_t;

typedef struct {
    bool in_use;
    uint8_t endpoint;
    basic_state_t basic_state;
    uint32_t basic_scheduled_at_ms;
    uint8_t reporting_requested;
    uint8_t reporting_configured;
    uint32_t reporting_requested_at_ms;
    uint8_t binding_requested;
    uint8_t binding_configured;
    uint32_t binding_requested_at_ms;
} endpoint_state_t;

typedef struct {
    slot_state_t state;
    uint32_t generation;
    gateway_device_id_t device;
    uint16_t previous_short_addr;
    uint8_t pending_jobs;
    uint8_t pending_requests;
    endpoint_state_t endpoints[GATEWAY_MAX_ENDPOINTS_PER_DEVICE];
} device_slot_t;

typedef struct {
    uint8_t index;
    uint32_t generation;
} device_ref_t;

device_slot_t *gateway_device_find_by_ieee(
    const uint8_t ieee[8], bool include_non_active);
device_slot_t *gateway_device_find_by_short(
    uint16_t short_addr, bool include_non_active);
device_ref_t gateway_device_ref_for(const device_slot_t *slot);
device_slot_t *gateway_device_from_ref(
    device_ref_t ref, bool include_non_active);
void gateway_device_maybe_reclaim(device_slot_t *slot);
device_slot_t *gateway_device_upsert(
    uint16_t short_addr, const uint8_t ieee[8]);
endpoint_state_t *gateway_device_endpoint_state(
    device_slot_t *slot, uint8_t endpoint, bool create);
''')

Path('main/gateway_device_state.c').write_text(r'''#include "gateway_device_state.h"

#include <limits.h>
#include <stddef.h>
#include <string.h>

static device_slot_t s_devices[GATEWAY_MAX_DEVICES];

static bool ieee_matches(const device_slot_t *slot, const uint8_t ieee[8])
{
    return ieee != NULL && slot->device.ieee_valid &&
        memcmp(slot->device.ieee, ieee, sizeof(slot->device.ieee)) == 0;
}

device_slot_t *gateway_device_find_by_ieee(
    const uint8_t ieee[8], bool include_non_active)
{
    for (size_t i = 0; ieee != NULL && i < GATEWAY_MAX_DEVICES; ++i) {
        if (s_devices[i].state != SLOT_EMPTY &&
            (include_non_active || s_devices[i].state == SLOT_ACTIVE) &&
            ieee_matches(&s_devices[i], ieee)) {
            return &s_devices[i];
        }
    }
    return NULL;
}

device_slot_t *gateway_device_find_by_short(
    uint16_t short_addr, bool include_non_active)
{
    for (size_t i = 0; i < GATEWAY_MAX_DEVICES; ++i) {
        if (s_devices[i].state != SLOT_EMPTY &&
            (include_non_active || s_devices[i].state == SLOT_ACTIVE) &&
            s_devices[i].device.short_addr == short_addr) {
            return &s_devices[i];
        }
    }
    return NULL;
}

device_ref_t gateway_device_ref_for(const device_slot_t *slot)
{
    return (device_ref_t){
        .index = (uint8_t)(slot - s_devices),
        .generation = slot->generation,
    };
}

device_slot_t *gateway_device_from_ref(
    device_ref_t ref, bool include_non_active)
{
    if (ref.index >= GATEWAY_MAX_DEVICES) {
        return NULL;
    }
    device_slot_t *slot = &s_devices[ref.index];
    if (slot->state == SLOT_EMPTY || slot->generation != ref.generation ||
        (!include_non_active && slot->state != SLOT_ACTIVE)) {
        return NULL;
    }
    return slot;
}

void gateway_device_maybe_reclaim(device_slot_t *slot)
{
    if (slot != NULL && slot->state == SLOT_LEAVING &&
        slot->pending_jobs == 0U && slot->pending_requests == 0U) {
        memset(slot->endpoints, 0, sizeof(slot->endpoints));
        memset(&slot->device, 0, sizeof(slot->device));
        slot->device.short_addr = GATEWAY_INVALID_SHORT_ADDR;
        slot->state = SLOT_EMPTY;
    }
}

static device_slot_t *allocate_device(uint16_t short_addr)
{
    for (size_t i = 0; i < GATEWAY_MAX_DEVICES; ++i) {
        if (s_devices[i].state == SLOT_EMPTY) {
            const uint32_t generation =
                s_devices[i].generation == UINT32_MAX ? 1U :
                s_devices[i].generation + 1U;
            memset(&s_devices[i], 0, sizeof(s_devices[i]));
            s_devices[i].state = SLOT_ACTIVE;
            s_devices[i].generation = generation;
            s_devices[i].device.short_addr = short_addr;
            s_devices[i].previous_short_addr = GATEWAY_INVALID_SHORT_ADDR;
            return &s_devices[i];
        }
    }
    return NULL;
}

device_slot_t *gateway_device_upsert(
    uint16_t short_addr, const uint8_t ieee[8])
{
    device_slot_t *slot = ieee == NULL ?
        gateway_device_find_by_short(short_addr, false) :
        gateway_device_find_by_ieee(ieee, true);
    if (slot == NULL) {
        slot = allocate_device(short_addr);
    }
    if (slot == NULL) {
        return NULL;
    }

    device_slot_t *old = gateway_device_find_by_short(short_addr, true);
    if (old != NULL && old != slot) {
        old->device.short_addr = GATEWAY_INVALID_SHORT_ADDR;
        old->state = SLOT_LEAVING;
        gateway_device_maybe_reclaim(old);
    }

    slot->state = SLOT_ACTIVE;
    if (slot->device.short_addr != GATEWAY_INVALID_SHORT_ADDR &&
        slot->device.short_addr != short_addr) {
        slot->previous_short_addr = slot->device.short_addr;
    }
    slot->device.short_addr = short_addr;
    if (ieee != NULL) {
        memcpy(slot->device.ieee, ieee, sizeof(slot->device.ieee));
        slot->device.ieee_valid = true;
    }
    return slot;
}

endpoint_state_t *gateway_device_endpoint_state(
    device_slot_t *slot, uint8_t endpoint, bool create)
{
    if (slot == NULL) {
        return NULL;
    }
    for (size_t i = 0; i < GATEWAY_MAX_ENDPOINTS_PER_DEVICE; ++i) {
        if (slot->endpoints[i].in_use &&
            slot->endpoints[i].endpoint == endpoint) {
            return &slot->endpoints[i];
        }
    }
    if (!create) {
        return NULL;
    }
    for (size_t i = 0; i < GATEWAY_MAX_ENDPOINTS_PER_DEVICE; ++i) {
        if (!slot->endpoints[i].in_use) {
            slot->endpoints[i].in_use = true;
            slot->endpoints[i].endpoint = endpoint;
            return &slot->endpoints[i];
        }
    }
    return NULL;
}
''')

Path('tests/host/test_gateway_device_state.c').write_text(r'''#include <assert.h>
#include <stdio.h>

#include "gateway_device_state.h"

static const uint8_t IEEE_A[8] = {1, 2, 3, 4, 5, 6, 7, 8};
static const uint8_t IEEE_B[8] = {8, 7, 6, 5, 4, 3, 2, 1};

int main(void)
{
    device_slot_t *a = gateway_device_upsert(0x1234U, IEEE_A);
    assert(a != NULL);
    assert(a->state == SLOT_ACTIVE);
    assert(a->device.short_addr == 0x1234U);
    assert(gateway_device_find_by_ieee(IEEE_A, false) == a);
    assert(gateway_device_find_by_short(0x1234U, false) == a);

    const device_ref_t first_ref = gateway_device_ref_for(a);
    assert(gateway_device_from_ref(first_ref, false) == a);

    device_slot_t *same = gateway_device_upsert(0x2345U, IEEE_A);
    assert(same == a);
    assert(a->previous_short_addr == 0x1234U);
    assert(a->device.short_addr == 0x2345U);
    assert(gateway_device_find_by_short(0x1234U, false) == NULL);

    a->pending_requests = 1U;
    device_slot_t *b = gateway_device_upsert(0x2345U, IEEE_B);
    assert(b != NULL && b != a);
    assert(b->state == SLOT_ACTIVE);
    assert(a->state == SLOT_LEAVING);
    assert(a->device.short_addr == GATEWAY_INVALID_SHORT_ADDR);
    assert(gateway_device_find_by_ieee(IEEE_A, false) == NULL);
    assert(gateway_device_find_by_ieee(IEEE_A, true) == a);
    assert(gateway_device_find_by_short(0x2345U, false) == b);

    a->pending_requests = 0U;
    gateway_device_maybe_reclaim(a);
    assert(a->state == SLOT_EMPTY);
    assert(gateway_device_from_ref(first_ref, true) == NULL);

    device_slot_t *a2 = gateway_device_upsert(0x3456U, IEEE_A);
    assert(a2 != NULL);
    assert(a2->generation != first_ref.generation);
    assert(gateway_device_from_ref(first_ref, true) == NULL);

    for (uint8_t ep = 1U; ep <= GATEWAY_MAX_ENDPOINTS_PER_DEVICE; ++ep) {
        endpoint_state_t *state = gateway_device_endpoint_state(a2, ep, true);
        assert(state != NULL);
        assert(state->endpoint == ep);
        assert(gateway_device_endpoint_state(a2, ep, false) == state);
    }
    assert(gateway_device_endpoint_state(a2, 99U, true) == NULL);
    assert(gateway_device_endpoint_state(NULL, 1U, true) == NULL);

    puts("gateway_device_state host tests passed");
    return 0;
}
''')

